// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

import {BANMToken} from "./BANMToken.sol";

contract BANMBridgeController is AccessControl, Pausable {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 public constant VAULT_MANAGER_ROLE = keccak256("VAULT_MANAGER_ROLE");

    BANMToken public immutable token;

    uint256 public dailyMintCap;
    uint256 public dailyReleaseCap;
    uint256 public mintedToday;
    uint256 public releasedToday;
    uint256 public capDay;

    mapping(bytes32 => bool) public mintExecutedForOrder;
    mapping(bytes32 => bool) public burnExecutedForOrder;
    mapping(bytes32 => bool) public releaseCompletedForOrder;

    struct ChainConfig {
        bool enabled;
        address router;
        address vault;
        string label;
    }

    mapping(uint256 => ChainConfig) public chainConfigs;

    event MintRequested(
        bytes32 indexed orderId,
        address indexed to,
        uint256 amount,
        uint256 feeAmount,
        string externalRef
    );
    event MintExecuted(
        bytes32 indexed orderId,
        address indexed to,
        uint256 amount,
        uint256 feeAmount,
        string externalRef
    );
    event MintRejected(bytes32 indexed orderId, string reason);

    event BurnRequested(bytes32 indexed orderId, address indexed from, uint256 amount, string externalRef);
    event BurnExecuted(bytes32 indexed orderId, address indexed from, uint256 amount, string externalRef);

    event ReleaseRequested(bytes32 indexed orderId, string animicaAddress, uint256 amount, string externalRef);
    event ReleaseCompleted(
        bytes32 indexed orderId,
        string animicaAddress,
        uint256 amount,
        string animicaTxHash
    );

    event ChainConfigured(uint256 indexed chainId, bool enabled, address router, address vault, string label);
    event CapsUpdated(uint256 dailyMintCap, uint256 dailyReleaseCap);

    constructor(address admin, BANMToken token_) {
        token = token_;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
        _grantRole(MINTER_ROLE, admin);
        _grantRole(BURNER_ROLE, admin);
        _grantRole(VAULT_MANAGER_ROLE, admin);
        capDay = _day();
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function setCaps(uint256 dailyMintCap_, uint256 dailyReleaseCap_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        dailyMintCap = dailyMintCap_;
        dailyReleaseCap = dailyReleaseCap_;
        emit CapsUpdated(dailyMintCap_, dailyReleaseCap_);
    }

    function configureChain(
        uint256 chainId,
        bool enabled,
        address router,
        address vault,
        string calldata label
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        chainConfigs[chainId] = ChainConfig({
            enabled: enabled,
            router: router,
            vault: vault,
            label: label
        });
        emit ChainConfigured(chainId, enabled, router, vault, label);
    }

    function executeMint(
        bytes32 orderId,
        address to,
        uint256 amount,
        uint256 feeAmount,
        string calldata externalRef
    ) external onlyRole(OPERATOR_ROLE) whenNotPaused {
        _rolloverDay();
        require(!mintExecutedForOrder[orderId], "mint already executed for order");
        if (dailyMintCap > 0) {
            require(mintedToday + amount <= dailyMintCap, "daily mint cap exceeded");
        }
        emit MintRequested(orderId, to, amount, feeAmount, externalRef);
        mintExecutedForOrder[orderId] = true;
        mintedToday += amount;
        token.mint(to, amount, orderId);
        emit MintExecuted(orderId, to, amount, feeAmount, externalRef);
    }

    function rejectMint(bytes32 orderId, string calldata reason) external onlyRole(OPERATOR_ROLE) {
        emit MintRejected(orderId, reason);
    }

    function registerBurn(
        bytes32 orderId,
        address from,
        uint256 amount,
        string calldata externalRef
    ) external onlyRole(VAULT_MANAGER_ROLE) {
        require(!burnExecutedForOrder[orderId], "burn already executed for order");
        emit BurnRequested(orderId, from, amount, externalRef);
        burnExecutedForOrder[orderId] = true;
        emit BurnExecuted(orderId, from, amount, externalRef);
    }

    function markReleaseRequested(
        bytes32 orderId,
        string calldata animicaAddress,
        uint256 amount,
        string calldata externalRef
    ) external onlyRole(OPERATOR_ROLE) {
        emit ReleaseRequested(orderId, animicaAddress, amount, externalRef);
    }

    function markReleaseCompleted(
        bytes32 orderId,
        string calldata animicaAddress,
        uint256 amount,
        string calldata animicaTxHash
    ) external onlyRole(OPERATOR_ROLE) {
        _rolloverDay();
        require(!releaseCompletedForOrder[orderId], "release already completed for order");
        if (dailyReleaseCap > 0) {
            require(releasedToday + amount <= dailyReleaseCap, "daily release cap exceeded");
        }
        releaseCompletedForOrder[orderId] = true;
        releasedToday += amount;
        emit ReleaseCompleted(orderId, animicaAddress, amount, animicaTxHash);
    }

    function _day() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }

    function _rolloverDay() internal {
        uint256 today = _day();
        if (today != capDay) {
            capDay = today;
            mintedToday = 0;
            releasedToday = 0;
        }
    }
}

contracts/BANMBridgeDepositRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {BANMToken} from "./BANMToken.sol";
import {BANMBridgeVault} from "./BANMBridgeVault.sol";

contract BANMBridgeDepositRouter is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for BANMToken;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    BANMToken public immutable token;
    BANMBridgeVault public immutable vault;

    mapping(bytes32 => bool) public depositRegistered;

    event DepositRegistered(
        bytes32 indexed orderId,
        address indexed sender,
        uint256 amount,
        address indexed vault
    );

    constructor(address admin, BANMToken token_, BANMBridgeVault vault_) {
        token = token_;
        vault = vault_;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function deposit(bytes32 orderId, uint256 amount) external whenNotPaused nonReentrant {
        require(amount > 0, "amount must be > 0");
        require(!depositRegistered[orderId], "order already deposited");
        depositRegistered[orderId] = true;

        token.safeTransferFrom(msg.sender, address(vault), amount);
        vault.registerDeposit(orderId, msg.sender, amount);
        emit DepositRegistered(orderId, msg.sender, amount, address(vault));
    }
}

contracts/BANMBridgeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {BANMToken} from "./BANMToken.sol";
import {BANMBridgeController} from "./BANMBridgeController.sol";

contract BANMBridgeVault is AccessControl, Pausable, ReentrancyGuard {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 public constant VAULT_MANAGER_ROLE = keccak256("VAULT_MANAGER_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant ROUTER_ROLE = keccak256("ROUTER_ROLE");

    BANMToken public immutable token;
    BANMBridgeController public immutable controller;

    struct DepositRecord {
        address sender;
        uint256 amount;
        bool burned;
        uint64 timestamp;
    }

    mapping(bytes32 => DepositRecord) public deposits;

    event DepositRegistered(
        bytes32 indexed orderId,
        address indexed sender,
        uint256 amount,
        address indexed router
    );
    event BurnRequested(bytes32 indexed orderId, address indexed sender, uint256 amount);
    event BurnExecuted(bytes32 indexed orderId, address indexed sender, uint256 amount);

    constructor(address admin, BANMToken token_, BANMBridgeController controller_) {
        token = token_;
        controller = controller_;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(BURNER_ROLE, admin);
        _grantRole(VAULT_MANAGER_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function registerDeposit(bytes32 orderId, address sender, uint256 amount)
        external
        whenNotPaused
        onlyRole(ROUTER_ROLE)
    {
        require(amount > 0, "amount must be > 0");
        DepositRecord storage record = deposits[orderId];
        require(record.timestamp == 0, "deposit already registered for order");
        deposits[orderId] = DepositRecord({
            sender: sender,
            amount: amount,
            burned: false,
            timestamp: uint64(block.timestamp)
        });
        emit DepositRegistered(orderId, sender, amount, msg.sender);
    }

    function burnForOrder(bytes32 orderId)
        external
        nonReentrant
        whenNotPaused
        onlyRole(BURNER_ROLE)
    {
        DepositRecord storage record = deposits[orderId];
        require(record.timestamp > 0, "deposit not found");
        require(!record.burned, "order already burned");
        record.burned = true;

        emit BurnRequested(orderId, record.sender, record.amount);
        token.bridgeBurn(record.amount, orderId);
        controller.registerBurn(orderId, record.sender, record.amount, "vault-burn");
        emit BurnExecuted(orderId, record.sender, record.amount);
    }
}

contracts/BANMToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract BANMToken is ERC20, ERC20Burnable, AccessControl, Pausable {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    event MintExecuted(bytes32 indexed orderId, address indexed to, uint256 amount);
    event BurnExecuted(bytes32 indexed orderId, address indexed account, uint256 amount);

    constructor(address admin) ERC20("BANM", "BANM") {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    function decimals() public pure override returns (uint8) {
        return 18;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function mint(address to, uint256 amount, bytes32 orderId) external onlyRole(MINTER_ROLE) whenNotPaused {
        _mint(to, amount);
        emit MintExecuted(orderId, to, amount);
    }

    function bridgeBurn(uint256 amount, bytes32 orderId) external onlyRole(BURNER_ROLE) whenNotPaused {
        _burn(msg.sender, amount);
        emit BurnExecuted(orderId, msg.sender, amount);
    }

    function _update(address from, address to, uint256 value) internal override whenNotPaused {
        super._update(from, to, value);
    }
}

